class Solution {
public:
 vector<int> getSubarrayBeauty(vector<int>& nums,int k,int x){
  int freq[101]={};vector<int> ans;
  for(int i=0;i<(int)nums.size();++i){
   ++freq[nums[i]+50];
   if(i>=k)--freq[nums[i-k]+50];
   if(i>=k-1){int need=x,beauty=0;
    for(int v=-50;v<0;++v){need-=freq[v+50];if(need<=0){beauty=v;break;}}
    ans.push_back(beauty);
   }
  }return ans;
 }
};
